window.SITE_BUSINESSES = [{"id":"vila-castelul-maria-banpotoc","name":"Vila Castelul Maria","category":{"ro":"Vilă turistică","en":"Tourist villa"},"area":"Hărău","townId":"harau","coords":[45.8605,23.0128],"hasReviews":true,"season":"tot-anul","images":["images/vila-castelul-maria-banpotoc.jpg"],"photoCredit":{"author":"Vila Castelul Maria","license":"material promoțional al afacerii","source":"https://castelulmaria.ro","sourceLabel":"castelulmaria.ro"},"ro":{"tagline":"Vilă în stil de mic castel cu turn, în satul Bănpotoc (comuna Hărău), la câțiva kilometri de Deva: grădină de 7.000 m², saună finlandeză și evenimente de familie.","description":["Vila Castelul Maria se află în satul Bănpotoc, comuna Hărău, în apropiere de Deva, și este o clădire veche, construită ca un mic castel cu turn, înconjurată de o grădină mare, de circa 7.000 m², cu flori și pomi. Castelul are trei apartamente cu decor propriu (roșu, albastru și bej) și o cameră în turn, cu vedere panoramică. La câteva minute de mers, Casa Maria adaugă șapte camere cu baie proprie, dintre care patru cu balcon.","Oaspeții pot rezerva separat o sesiune în sauna finlandeză cu vedere spre grădină. Micul dejun se servește la bufet, iar cina se comandă din timp. Pentru nunți mici, mese festive, petreceri și mese de afaceri există două saloane și o terasă acoperită, pentru cel mult 40 de persoane. Ca puncte de plecare apropiate sunt Cetatea Devei, Castelul Corvinilor din Hunedoara, Parcul Dendrologic Simeria și cetățile dacice din Munții Orăștiei."],"facts":[{"label":"Locație","value":"Sat Bănpotoc nr. 20, comuna Hărău"},{"label":"Cazare","value":"3 apartamente și o cameră în turn la Castelul Maria; 7 camere la Casa Maria"},{"label":"Facilități","value":"grădină de 7.000 m², saună finlandeză, saloane și terasă pentru evenimente (max. 40 de persoane)"},{"label":"Check-in / check-out","value":"16:00–22:00, pe bază de rezervare / până la 11:00"},{"label":"Contact","value":"tel. 0722 382 212 · luminita.castelulmaria@gmail.com · castelulmaria.ro"}]},"en":{"name":"Castelul Maria Villa, Bănpotoc","tagline":"A villa built as a small castle with a tower, in the village of Bănpotoc (Hărău commune), a few kilometres from Deva: a 7,000 sq m garden, a Finnish sauna and family events.","description":["Castelul Maria Villa stands in the village of Bănpotoc, Hărău commune, near Deva. It is an old building designed as a small castle with a tower, set in a large garden of about 7,000 sq m with flowers and fruit trees. The castle has three apartments with their own decor (red, blue and beige) and a tower room with panoramic views. A few minutes' walk away, Casa Maria adds seven rooms with private bathrooms, four of them with a balcony.","Guests can book a session in the Finnish sauna overlooking the garden separately. Breakfast is served as a buffet, and dinner is ordered in advance. For small weddings, festive dinners, parties and business meals there are two dining rooms and a covered terrace, for up to 40 people. Nearby starting points include Deva Fortress, Corvin Castle in Hunedoara, the Simeria Dendrological Park and the Dacian fortresses of the Orăștie Mountains."],"facts":[{"label":"Location","value":"Bănpotoc village no. 20, Hărău commune"},{"label":"Accommodation","value":"3 apartments and a tower room at Castelul Maria; 7 rooms at Casa Maria"},{"label":"Facilities","value":"7,000 sq m garden, Finnish sauna, dining rooms and terrace for events (max. 40 people)"},{"label":"Check-in / check-out","value":"16:00–22:00, by reservation / until 11:00"},{"label":"Contact","value":"phone +40 722 382 212 · luminita.castelulmaria@gmail.com · castelulmaria.ro"}]}},{"id":"conacul-radacinilor","name":"Conacul Rădăcinilor","category":{"ro":"Hotel & restaurant","en":"Hotel & restaurant"},"area":"Petrila","hasReviews":true,"season":"tot-anul","images":["images/conacul-radacinilor.jpg"],"photoCredit":{"author":"Conacul Rădăcinilor","license":"material promoțional al afacerii","source":"https://www.conaculradacinilor.ro","sourceLabel":"conaculradacinilor.ro"},"ro":{"tagline":"Complex hotelier de tip conac, deschis în 2023 în Cheile Jietului, cu spa, restaurant și drumeții ghidate.","description":["Conacul Rădăcinilor este un complex hotelier, restaurant și agrement deschis în 2023 pe strada Jiet (DN7A), în Cheile Jietului, pe teritoriul orașului Petrila, în drum spre Transalpina. Arhitectura rustică, cu lemn masiv și vegetație, adăpostește peste 25 de camere, o zonă de wellness & spa cu jacuzzi și saună încălzită, o cameră de salinoterapie, restaurant, „Green Bar”, terasă și spații pentru evenimente și conferințe.","Complexul organizează drumeții montane ghidate și are un parteneriat cu un centru ecvestru din apropiere (Keops Horses), fiind un punct de plecare potrivit atât pentru un weekend de relaxare, cât și pentru vizitarea Cheilor Jiețului și a platoului Parâng."],"facts":[{"label":"Locație","value":"Str. Jiet, DN7A, Cheile Jietului, Petrila"},{"label":"Deschis","value":"2023"},{"label":"Facilități","value":"peste 25 de camere, spa, jacuzzi, saună, salină, restaurant, terasă"},{"label":"Contact","value":"tel. 0738 777 711 · conaculradacinilor.ro"}]},"en":{"tagline":"A manor-style hotel complex opened in 2023 in the Jieț gorge, with a spa, restaurant and guided hikes.","description":["Conacul Rădăcinilor (\"Manor of Roots\") is a hotel, restaurant and leisure complex opened in 2023 on Jiet Street (DN7A), in the Jieț Gorge, within Petrila town, on the way to the Transalpina road. Its rustic architecture, built with solid wood and greenery, houses over 25 rooms, a wellness & spa area with a jacuzzi and heated sauna, a salt therapy room, a restaurant, a \"Green Bar\", a terrace, and event and conference spaces.","The complex runs guided mountain hikes and partners with a nearby equestrian centre (Keops Horses), making it a good base both for a relaxing weekend and for exploring the Jieț gorge and the Parâng plateau."],"facts":[{"label":"Location","value":"Jiet Street, DN7A, Jieț Gorge, Petrila"},{"label":"Opened","value":"2023"},{"label":"Facilities","value":"25+ rooms, spa, jacuzzi, sauna, salt room, restaurant, terrace"},{"label":"Contact","value":"phone +40 738 777 711 · conaculradacinilor.ro"}]}},{"id":"casa-lupeni","name":"Casa Lupeni","category":{"ro":"Cazare","en":"Accommodation"},"area":"Lupeni","hasReviews":true,"season":"tot-anul","images":["images/casa-lupeni.jpg"],"photoCredit":{"author":"Casa Lupeni","license":"material promoțional al afacerii","source":"https://www.booking.com/hotel/ro/casa-lupeni-lupeni1.html","sourceLabel":"Booking.com"},"ro":{"tagline":"Pensiune mică, cu 6 camere și jacuzzi în aer liber, pe strada Bărbăteni din Lupeni.","description":["Casa Lupeni este o pensiune de dimensiuni mici, situată pe strada Bărbăteni nr. 58, în Lupeni, cu 6 camere (duble, triple și un apartament cu două camere), fiecare cu baie proprie. Oferă parcare privată gratuită, cu 10 locuri supravegheate video, wi-fi în spațiile comune și grădină.","Punctul de atracție al pensiunii este jacuzzi-ul în aer liber, disponibil contra cost, iar locația este un punct de plecare comod spre stațiunea Straja și spre traseele din Valea Jiului. Pensiunea nu are restaurant propriu, tarifele afișate nefiind cu masă inclusă."],"facts":[{"label":"Adresă","value":"Str. Bărbăteni nr. 58, Lupeni"},{"label":"Camere","value":"6 camere (duble, triple, apartament), baie proprie"},{"label":"Facilități","value":"parcare privată, wi-fi, grădină, jacuzzi în aer liber (contra cost)"},{"label":"Contact","value":"tel. 0364 431 808"}]},"en":{"tagline":"A small 6-room guesthouse with an outdoor jacuzzi on Bărbăteni Street in Lupeni.","description":["Casa Lupeni is a small guesthouse on Bărbăteni Street no. 58 in Lupeni, with 6 rooms (double, triple and a two-room apartment), each with a private bathroom. It offers free private parking with 10 video-monitored spaces, wi-fi in common areas and a garden.","The guesthouse's highlight is its outdoor jacuzzi, available for an extra fee, and the location is a convenient base for the Straja resort and the hiking trails of the Jiu Valley. There is no restaurant on site, so the listed rates do not include meals."],"facts":[{"label":"Address","value":"Bărbăteni Street no. 58, Lupeni"},{"label":"Rooms","value":"6 rooms (double, triple, apartment), private bathroom"},{"label":"Facilities","value":"private parking, wi-fi, garden, outdoor jacuzzi (extra fee)"},{"label":"Contact","value":"phone +40 364 431 808"}]}},{"id":"hotel-sarmis-deva","name":"Hotel Sarmis","category":{"ro":"Cazare","en":"Accommodation"},"area":"Deva","hasReviews":true,"season":"tot-anul","images":["images/hotel-sarmis-deva.jpg"],"photoCredit":{"author":"Hotel Sarmis","license":"material promoțional al afacerii","source":"https://www.unitahotels.ro/hotel-sarmis-deva","sourceLabel":"unitahotels.ro"},"ro":{"tagline":"Hotel de 3 stele cu 117 camere, pe strada principală din centrul Devei.","description":["Hotel Sarmis este un hotel de 3 stele situat pe strada Mareșal Averescu nr. 7, în centrul orașului Deva, la mai puțin de un kilometru de gară și autogară. Dispune de 117 camere și apartamente, majoritatea cu balcon, minibar și TV, precum și de un restaurant propriu cu bucătărie românească și internațională, servită în salon sau pe terasă.","Fiind unul dintre cele mai mari hoteluri din oraș, este folosit atât pentru sejururi turistice, cât și pentru cazare de afaceri și evenimente; recepția funcționează non-stop, iar micul dejun, parcarea și internetul wi-fi sunt incluse în tarif."],"facts":[{"label":"Locație","value":"Str. Mareșal Averescu nr. 7, Deva"},{"label":"Categorie","value":"3 stele, 117 camere"},{"label":"Facilități","value":"restaurant propriu, parcare gratuită, wi-fi, mic dejun inclus"},{"label":"Contact","value":"tel. 0254 214 731 · sarmis.deva@unita-turism.ro"}]},"en":{"tagline":"A 3-star hotel with 117 rooms on Deva's main street, in the city centre.","description":["Hotel Sarmis is a 3-star hotel at 7 Mareșal Averescu Street, in central Deva, less than a kilometre from the train and bus stations. It has 117 rooms and suites, most with a balcony, minibar and TV, plus its own restaurant serving Romanian and international dishes, indoors or on the terrace.","As one of the largest hotels in town, it is used for both tourist stays and business travel or events; the front desk is open 24 hours, and breakfast, parking and wi-fi are included in the rate."],"facts":[{"label":"Location","value":"7 Mareșal Averescu Street, Deva"},{"label":"Category","value":"3 stars, 117 rooms"},{"label":"Facilities","value":"in-house restaurant, free parking, wi-fi, breakfast included"},{"label":"Contact","value":"phone +40 254 214 731 · sarmis.deva@unita-turism.ro"}]}},{"id":"cocosul-de-aur-deva","name":"Cocoșul de Aur","category":{"ro":"Restaurant","en":"Restaurant"},"area":"Deva","hasReviews":true,"season":"tot-anul","images":["images/cocosul-de-aur-deva.jpg"],"photoCredit":{"author":"Cocoșul de Aur Deva","license":"material promoțional al afacerii","source":"https://www.facebook.com/cocosuldeaurdeva","sourceLabel":"Facebook"},"ro":{"tagline":"Restaurant cu specific românesc, lipit de Sinagoga din centrul Devei.","description":["Cocoșul de Aur este un restaurant cu specific tradițional românesc, situat pe Bulevardul Iuliu Maniu nr. 9, chiar în centrul Devei, lângă clădirea Sinagogii. Are 60 de locuri în interior și o terasă încălzită cu încă 40 de locuri, iar meniul îmbină ciorbe și fripturi la grătar, gătite după rețete clasice, cu câteva preparate internaționale."],"facts":[{"label":"Adresă","value":"Bd. Iuliu Maniu nr. 9, Deva"},{"label":"Specific","value":"bucătărie tradițională românească"},{"label":"Capacitate","value":"60 de locuri interior + terasă încălzită, 40 de locuri"},{"label":"Contact","value":"tel. 0767 651 253"}]},"en":{"tagline":"A traditional Romanian restaurant right next to the Deva synagogue.","description":["Cocoșul de Aur (\"The Golden Rooster\") is a traditional Romanian restaurant at 9 Iuliu Maniu boulevard, in central Deva, next to the synagogue building. It seats 60 indoors plus another 40 on a heated terrace, and its menu combines soups and grilled meats cooked to classic recipes with a few international dishes."],"facts":[{"label":"Address","value":"9 Iuliu Maniu boulevard, Deva"},{"label":"Cuisine","value":"traditional Romanian"},{"label":"Capacity","value":"60 seats indoors + heated terrace, 40 seats"},{"label":"Contact","value":"phone +40 767 651 253"}]}},{"id":"casa-rustica-deva","name":"Casa Rustică","category":{"ro":"Restaurant","en":"Restaurant"},"area":"Deva","hasReviews":true,"season":"tot-anul","images":["images/casa-rustica-deva.jpg"],"photoCredit":{"author":"Casa Rustică","license":"material promoțional al afacerii","source":"https://casarusticadeva.ro","sourceLabel":"casarusticadeva.ro"},"ro":{"tagline":"Bistro-pizzerie cu specific italian, vizavi de centrul comercial Ulpia din Deva.","description":["Casa Rustică este un bistro-pizzerie cu specific italian, situat pe Aleea Transilvaniei, vizavi de centrul comercial Ulpia din Deva. Meniul cuprinde pizza la cuptor, paste, salate și preparate internaționale, într-o atmosferă rustică, potrivită atât pentru mese rapide, cât și pentru comenzi la pachet."],"facts":[{"label":"Adresă","value":"Aleea Transilvaniei, bl. 7, sc. 2, parter, Deva"},{"label":"Specific","value":"pizza, paste, bucătărie italiană și internațională"},{"label":"Contact","value":"tel. 0254 222 300"}]},"en":{"tagline":"An Italian-style bistro and pizzeria across from the Ulpia mall in Deva.","description":["Casa Rustică is an Italian-style bistro and pizzeria on Aleea Transilvaniei, across from the Ulpia shopping centre in Deva. The menu includes oven-baked pizza, pasta, salads and international dishes, in a rustic setting suited to both quick meals and takeaway orders."],"facts":[{"label":"Address","value":"Aleea Transilvaniei, bl. 7, sc. 2, ground floor, Deva"},{"label":"Cuisine","value":"pizza, pasta, Italian and international"},{"label":"Contact","value":"phone +40 254 222 300"}]}},{"id":"pensiunea-la-fontaine-hunedoara","name":"Pensiunea La Fontaine","category":{"ro":"Cazare","en":"Accommodation"},"area":"Hunedoara","hasReviews":true,"season":"tot-anul","images":["images/pensiunea-la-fontaine-hunedoara.jpg"],"photoCredit":{"author":"Pensiunea La Fontaine","license":"material promoțional al afacerii","source":"https://lafontaine.ro","sourceLabel":"lafontaine.ro"},"ro":{"tagline":"Pensiune cu 10 camere și grădină, la câteva minute de mers pe jos de Castelul Corvinilor.","description":["Pensiunea La Fontaine este situată pe strada Rotarilor nr. 4, în centrul Hunedoarei, la câteva minute de mers pe jos de Castelul Corvinilor — unele camere au vedere directă spre castel. Dispune de 10 camere (duble, twin și de familie), restaurant propriu, bar și o grădină amenajată pentru mese în aer liber.","Pensiunea oferă parcare gratuită și wi-fi atât în camere, cât și în grădină, fiind o opțiune potrivită pentru un sejur axat pe vizitarea cetății și a orașului vechi."],"facts":[{"label":"Adresă","value":"Str. Rotarilor nr. 4, Hunedoara"},{"label":"Camere","value":"10 camere (duble, twin, de familie)"},{"label":"Facilități","value":"restaurant, bar, grădină, parcare gratuită, wi-fi"},{"label":"Contact","value":"tel. 0770 235 524 · rezervare@lafontaine.ro · lafontaine.ro"}]},"en":{"tagline":"A 10-room guesthouse with a garden, a few minutes' walk from Corvin Castle.","description":["Pensiunea La Fontaine is on Rotarilor Street no. 4, in central Hunedoara, a few minutes' walk from Corvin Castle — some rooms have a direct view of the castle. It has 10 rooms (double, twin and family), its own restaurant, a bar and a landscaped garden for outdoor dining.","The guesthouse offers free parking and wi-fi both in the rooms and in the garden, making it a good choice for a stay focused on the fortress and the old town."],"facts":[{"label":"Address","value":"4 Rotarilor Street, Hunedoara"},{"label":"Rooms","value":"10 rooms (double, twin, family)"},{"label":"Facilities","value":"restaurant, bar, garden, free parking, wi-fi"},{"label":"Contact","value":"phone +40 770 235 524 · rezervare@lafontaine.ro · lafontaine.ro"}]}},{"id":"curtea-veche-hunedoara","name":"Curtea Veche","category":{"ro":"Hotel & restaurant","en":"Hotel & restaurant"},"area":"Hunedoara","hasReviews":true,"season":"tot-anul","images":["images/curtea-veche-hunedoara.jpg"],"photoCredit":{"author":"Curtea Veche","license":"material promoțional al afacerii","source":"https://curteavechehunedoara.ro","sourceLabel":"curteavechehunedoara.ro"},"ro":{"tagline":"Fost han vechi, azi pensiune și restaurant cu bucătărie tradițională hunedoreană.","description":["Curtea Veche este un complex de cazare și restaurant amenajat într-un vechi han din Hunedoara, pe strada Cernei nr. 2, la poalele Castelului Corvinilor. Pensiunea oferă camere single, duble, triple și de familie, iar restaurantul servește preparate din bucătăria tradițională hunedoreană — friptură cu garnitură „ca la bunica”, produse de patiserie coapte la cuptorul cu lemne și tocănițe gătite lent în oale de lut.","Complexul are curte spațioasă cu șemineu pe lemne și spații destinate evenimentelor, fiind unul dintre puținele locuri din oraș care combină cazare și restaurant sub același acoperiș, în imediata apropiere a cetății."],"facts":[{"label":"Adresă","value":"Str. Cernei nr. 2, Hunedoara"},{"label":"Specific","value":"bucătărie tradițională hunedoreană, produse la cuptorul cu lemne"},{"label":"Program","value":"10:00–22:00, zilnic"},{"label":"Contact","value":"pensiune tel. 0772 028 207 · restaurant tel. 0770 123 333 · curteavechehunedoara.ro"}]},"en":{"tagline":"A former old inn, now a guesthouse and restaurant with traditional Hunedoara cuisine.","description":["Curtea Veche is an accommodation and restaurant complex set up in an old inn in Hunedoara, at 2 Cernei Street, at the foot of Corvin Castle. The guesthouse offers single, double, triple and family rooms, while the restaurant serves traditional Hunedoara dishes — roasted meat with sides \"like grandmother used to make\", wood-fired oven pastries and stews slow-cooked in clay pots.","The complex has a spacious courtyard with a wood-burning fireplace and event spaces, making it one of the few places in town that combines lodging and dining under one roof, right next to the fortress."],"facts":[{"label":"Address","value":"2 Cernei Street, Hunedoara"},{"label":"Cuisine","value":"traditional Hunedoara cuisine, wood-fired oven dishes"},{"label":"Hours","value":"10:00 AM–10:00 PM, daily"},{"label":"Contact","value":"guesthouse phone +40 772 028 207 · restaurant phone +40 770 123 333 · curteavechehunedoara.ro"}]}},{"id":"eden-by-werk-hunedoara","name":"Eden by Werk","category":{"ro":"Restaurant","en":"Restaurant"},"area":"Hunedoara","hasReviews":true,"season":"tot-anul","images":["images/eden-by-werk-hunedoara.jpg"],"photoCredit":{"author":"WERK Hotel & Spa","license":"material promoțional al afacerii","source":"https://hotelwerk.ro","sourceLabel":"hotelwerk.ro"},"ro":{"tagline":"Restaurant modern cu vedere spre Castelul Corvinilor, în cadrul complexului Werk Hotel & Spa.","description":["Eden by Werk este restaurantul complexului Werk Hotel & Spa, situat pe strada Voinei nr. 2A din Hunedoara, la câteva minute de mers pe jos de Castelul Corvinilor, cu vedere directă spre cetate. Meniul, semnat de un bucătar propriu, combină bucătăria contemporană cu influențe internaționale, într-un decor modern."],"facts":[{"label":"Adresă","value":"Str. Voinei nr. 2A, Hunedoara"},{"label":"Specific","value":"bucătărie contemporană, meniu de autor"},{"label":"Reper","value":"la câteva minute de Castelul Corvinilor, în cadrul Werk Hotel & Spa"}]},"en":{"tagline":"A modern restaurant with a view of Corvin Castle, inside the Werk Hotel & Spa complex.","description":["Eden by Werk is the restaurant of the Werk Hotel & Spa complex, at 2A Voinei Street in Hunedoara, a few minutes' walk from Corvin Castle, with a direct view of the fortress. The menu, created by an in-house chef, blends contemporary cooking with international influences in a modern setting."],"facts":[{"label":"Address","value":"2A Voinei Street, Hunedoara"},{"label":"Cuisine","value":"contemporary, chef's menu"},{"label":"Landmark","value":"a few minutes from Corvin Castle, inside Werk Hotel & Spa"}]}},{"id":"hotel-petrosani","name":"Hotel Petroșani","category":{"ro":"Cazare","en":"Accommodation"},"area":"Petroșani","hasReviews":true,"season":"tot-anul","images":["images/hotel-petrosani.jpg"],"photoCredit":{"author":"Hotel Petroșani","license":"material promoțional al afacerii","source":"https://www.hotelpetrosani.com","sourceLabel":"hotelpetrosani.com"},"ro":{"tagline":"Hotel central, construit în 1987, lângă Parcul Central din Petroșani.","description":["Hotel Petroșani este situat pe strada 1 Decembrie 1918 nr. 110, în centrul municipiului, chiar lângă Parcul Central, la câțiva pași de principalele obiective din oraș. Construit în 1987, oferă camere twin, duble și apartamente de tip superior, cu wi-fi gratuit, sală de fitness și zonă de recepție/lounge.","Poziția centrală îl recomandă atât pentru vizite turistice în Valea Jiului, cât și pentru cazare de afaceri sau tranzit spre stațiunile de schi Parâng și Straja."],"facts":[{"label":"Adresă","value":"Str. 1 Decembrie 1918 nr. 110, Petroșani"},{"label":"Deschis","value":"1987"},{"label":"Camere","value":"twin, duble, apartamente superior"},{"label":"Contact","value":"tel. 0721 205 023 · contact@hotelpetrosani.com · hotelpetrosani.com"}]},"en":{"tagline":"A central hotel, built in 1987, next to Petroșani's Central Park.","description":["Hotel Petroșani is located at 110 1 Decembrie 1918 Street, in the city centre, right next to Central Park, a short walk from the town's main sights. Built in 1987, it offers twin, double and superior apartment rooms, with free wi-fi, a fitness room and a reception/lounge area.","Its central location makes it suitable both for sightseeing trips around the Jiu Valley and for business stays or as a stopover on the way to the Parâng and Straja ski resorts."],"facts":[{"label":"Address","value":"110 1 Decembrie 1918 Street, Petroșani"},{"label":"Opened","value":"1987"},{"label":"Rooms","value":"twin, double, superior apartments"},{"label":"Contact","value":"phone +40 721 205 023 · contact@hotelpetrosani.com · hotelpetrosani.com"}]}},{"id":"complex-keops-petrosani","name":"Complex Keops","category":{"ro":"Restaurant","en":"Restaurant"},"area":"Petroșani","hasReviews":true,"season":"tot-anul","images":["images/complex-keops-petrosani.jpg"],"photoCredit":{"author":"Complex Keops","license":"material promoțional al afacerii","source":"https://www.complexkeops.ro","sourceLabel":"complexkeops.ro"},"ro":{"tagline":"Restaurant și complex de agrement din 2005, cu centru ecvestru propriu, în Petroșani.","description":["Complex Keops funcționează din 2005 pe strada 1 Decembrie 1918 nr. 137, în Petroșani, ca restaurant cu terasă și zonă de club, servind atât preparate tradiționale românești, cât și bucătărie internațională, cu servicii de catering la cerere.","Complexul include și un centru ecvestru propriu (Keops Horses), cu lecții de călărie și trasee montane cu caii, precum și spații de joacă pentru copii — fiind partenerul apropiat al hotelului Conacul Rădăcinilor din Cheile Jietului."],"facts":[{"label":"Adresă","value":"Str. 1 Decembrie 1918 nr. 137, Petroșani"},{"label":"Deschis","value":"2005"},{"label":"Specific","value":"bucătărie românească și internațională, catering, centru ecvestru"},{"label":"Contact","value":"tel. 0730 072 626"}]},"en":{"tagline":"A restaurant and leisure complex open since 2005, with its own equestrian centre, in Petroșani.","description":["Complex Keops has operated since 2005 at 137 1 Decembrie 1918 Street in Petroșani, as a restaurant with a terrace and a club area, serving both traditional Romanian dishes and international cuisine, with catering services on request.","The complex also includes its own equestrian centre (Keops Horses), with riding lessons and mountain trail rides, plus a children's play area — it is the close partner of the Conacul Rădăcinilor hotel in the Jieț gorge."],"facts":[{"label":"Address","value":"137 1 Decembrie 1918 Street, Petroșani"},{"label":"Opened","value":"2005"},{"label":"Cuisine","value":"Romanian and international, catering, equestrian centre"},{"label":"Contact","value":"phone +40 730 072 626"}]}},{"id":"pensiunea-avy-hateg","name":"Pensiunea Avy","category":{"ro":"Cazare","en":"Accommodation"},"area":"Hațeg","hasReviews":true,"season":"tot-anul","images":["images/pensiunea-avy-hateg.jpg"],"photoCredit":{"author":"Pensiunea Avy","license":"material promoțional al afacerii","source":"https://pensiunea-avy.ro","sourceLabel":"pensiunea-avy.ro"},"ro":{"tagline":"Pensiune cu 13 camere, vizavi de benzinăria Petrom, la 2 minute de centrul Hațegului.","description":["Pensiunea Avy este situată în Hațeg, vizavi de benzinăria Petrom, la aproximativ 2 minute de mers pe jos de centrul orașului. Are 13 camere moderne, cu o capacitate totală de 27 de locuri, dotate cu aer condiționat, baie proprie, TV LCD, wi-fi gratuit, minifrigider și uscător de păr.","Pensiunea pune la dispoziția oaspeților un pavilion cu grătar și o bucătărie complet echipată, fiind un punct de plecare bun spre Parcul Național Retezat și Geoparcul Țara Hațegului."],"facts":[{"label":"Adresă","value":"Hațeg, vizavi de benzinăria Petrom"},{"label":"Camere","value":"13 camere, 27 de locuri"},{"label":"Facilități","value":"pavilion cu grătar, bucătărie pentru oaspeți, wi-fi"},{"label":"Contact","value":"tel. 0762 642 046 · pensiunea-avy.ro"}]},"en":{"tagline":"A 13-room guesthouse across from the Petrom station, 2 minutes from central Hațeg.","description":["Pensiunea Avy is located in Hațeg, across from the Petrom fuel station, about a 2-minute walk from the town centre. It has 13 modern rooms with a total capacity of 27 guests, fitted with air conditioning, a private bathroom, LCD TV, free wi-fi, a mini-fridge and a hairdryer.","The guesthouse provides guests with a barbecue pavilion and a fully equipped kitchen, making it a good starting point for Retezat National Park and the Hațeg Country Geopark."],"facts":[{"label":"Address","value":"Hațeg, opposite the Petrom station"},{"label":"Rooms","value":"13 rooms, 27 guests"},{"label":"Facilities","value":"barbecue pavilion, guest kitchen, wi-fi"},{"label":"Contact","value":"phone +40 762 642 046 · pensiunea-avy.ro"}]}},{"id":"avy-wine-dine-hateg","name":"Avy Wine & Dine","category":{"ro":"Restaurant","en":"Restaurant"},"area":"Hațeg","hasReviews":true,"season":"tot-anul","images":["images/avy-wine-dine-hateg.jpg"],"photoCredit":{"author":"Avy Wine & Dine","license":"material promoțional al afacerii","source":"https://restaurant-avy.ro","sourceLabel":"restaurant-avy.ro"},"ro":{"tagline":"Restaurant cu bucătărie mediteraneeană, pe strada Tudor Arghezi din Hațeg.","description":["Avy Wine & Dine este un restaurant situat pe strada Tudor Arghezi nr. 28, în Hațeg, cu un meniu de inspirație mediteraneeană, cu influențe italiene și franțuzești, alături de o listă de vinuri dedicată. Este unul dintre restaurantele cele mai bine cotate din oraș pe platformele de recenzii."],"facts":[{"label":"Adresă","value":"Str. Tudor Arghezi nr. 28, Hațeg"},{"label":"Specific","value":"bucătărie mediteraneeană, italiană și franțuzească, listă de vinuri"},{"label":"Contact","value":"tel. 0786 725 000 · restaurant-avy.ro"}]},"en":{"tagline":"A restaurant with Mediterranean cuisine, on Tudor Arghezi Street in Hațeg.","description":["Avy Wine & Dine is a restaurant at 28 Tudor Arghezi Street in Hațeg, with a Mediterranean-inspired menu carrying Italian and French influences, alongside a dedicated wine list. It is one of the highest-rated restaurants in town on review platforms."],"facts":[{"label":"Address","value":"28 Tudor Arghezi Street, Hațeg"},{"label":"Cuisine","value":"Mediterranean, Italian and French, wine list"},{"label":"Contact","value":"phone +40 786 725 000 · restaurant-avy.ro"}]}},{"id":"pensiunea-jorja-orastie","name":"Pensiunea Jorja","category":{"ro":"Cazare","en":"Accommodation"},"area":"Orăștie","hasReviews":true,"season":"tot-anul","images":["images/pensiunea-jorja-orastie.jpg"],"photoCredit":{"author":"Pensiunea Jorja","license":"material promoțional al afacerii","source":"https://www.facebook.com/pensiuneajorja1","sourceLabel":"Facebook"},"ro":{"tagline":"Pensiune cu 14 camere în centrul Orăștiei, la 350 m de un magazin Lidl.","description":["Pensiunea Jorja este situată pe Bulevardul Nicolae Bălcescu nr. 30, în centrul orașului Orăștie, la aproximativ 350 de metri de un magazin Lidl și 3 km de gară. Dispune de 14 camere — single, duble și apartamente — cu o capacitate totală de 36 de locuri, fiecare cu baie proprie, TV și încălzire centrală.","Pensiunea are sală de mese, grătar propriu și acceptă animale de companie, fiind o bază convenabilă pentru vizitarea cetăților dacice din Munții Orăștiei, aflate la aproximativ 38 km."],"facts":[{"label":"Adresă","value":"Bd. Nicolae Bălcescu nr. 30, Orăștie"},{"label":"Camere","value":"14 camere, 36 de locuri"},{"label":"Facilități","value":"sală de mese, grătar, acceptă animale, parcare"},{"label":"Contact","value":"tel. 0254 240 013 / 0254 241 574"}]},"en":{"tagline":"A 14-room guesthouse in central Orăștie, 350 m from a Lidl store.","description":["Pensiunea Jorja is located at 30 Nicolae Bălcescu boulevard, in central Orăștie, about 350 metres from a Lidl store and 3 km from the train station. It has 14 rooms — single, double and apartments — with a total capacity of 36 guests, each with a private bathroom, TV and central heating.","The guesthouse has a dining room, its own barbecue and accepts pets, making it a convenient base for visiting the Dacian fortresses in the Orăștie Mountains, about 38 km away."],"facts":[{"label":"Address","value":"30 Nicolae Bălcescu boulevard, Orăștie"},{"label":"Rooms","value":"14 rooms, 36 guests"},{"label":"Facilities","value":"dining room, barbecue, pets allowed, parking"},{"label":"Contact","value":"phone +40 254 240 013 / +40 254 241 574"}]}},{"id":"bistro-merinde-orastie","name":"Bistro Merinde","category":{"ro":"Restaurant","en":"Restaurant"},"area":"Orăștie","hasReviews":true,"season":"tot-anul","images":["images/bistro-merinde-orastie.jpg"],"photoCredit":{"author":"Bistro Merinde","license":"material promoțional al afacerii","source":"https://www.facebook.com/bistromerinde","sourceLabel":"Facebook"},"ro":{"tagline":"Bistro cu meniu românesc și internațional, într-una dintre casele vechi din Orăștie.","description":["Bistro Merinde este situat pe strada Octavian Goga nr. 31, la parterul uneia dintre cele mai vechi case din Orăștie, cu design contemporan. Meniul este de inspirație românească și internațională, servit într-o atmosferă casual, potrivită atât pentru o masă rapidă, cât și pentru o oprire mai lungă pentru cei care circulă pe autostrada A1 între Sibiu și Lugoj."],"facts":[{"label":"Adresă","value":"Str. Octavian Goga nr. 31, Orăștie"},{"label":"Specific","value":"bucătărie românească și internațională contemporană"},{"label":"Program","value":"luni–vineri 10:00–21:00/22:00, sâmbătă 10:00–18:00, duminică închis"},{"label":"Contact","value":"tel. 0728 653 798"}]},"en":{"tagline":"A bistro with a Romanian and international menu, in one of Orăștie's old houses.","description":["Bistro Merinde is located at 31 Octavian Goga Street, on the ground floor of one of the oldest houses in Orăștie, with a contemporary design. The menu is inspired by Romanian and international cuisine, served in a casual setting suited both to a quick meal and to a longer stop for travellers on the A1 motorway between Sibiu and Lugoj."],"facts":[{"label":"Address","value":"31 Octavian Goga Street, Orăștie"},{"label":"Cuisine","value":"contemporary Romanian and international"},{"label":"Hours","value":"Mon–Fri 10:00 AM–9:00/10:00 PM, Sat 10:00 AM–6:00 PM, closed Sun"},{"label":"Contact","value":"phone +40 728 653 798"}]}},{"id":"pensiunea-irina-brad","name":"Pensiunea Irina","category":{"ro":"Cazare","en":"Accommodation"},"area":"Brad","hasReviews":true,"season":"tot-anul","images":["images/pensiunea-irina-brad.jpg"],"photoCredit":{"author":"Pensiunea Irina","license":"material promoțional al afacerii","source":"https://pensiuneairina.ro","sourceLabel":"pensiuneairina.ro"},"ro":{"tagline":"Pensiune de familie deschisă în 2001, cu 5 camere duble, în Brad.","description":["Pensiunea Irina funcționează din 2001 pe strada Vânătorilor nr. 20, în municipiul Brad, fiind clasificată la 2 stele de Ministerul Turismului. Are 5 camere duble, cu o capacitate totală de 10 locuri, fiecare cu baie proprie, aer condiționat, TV LED și încălzire proprie.","Pensiunea dispune de parcare și zonă de luat masa cu chicinetă, fiind o opțiune bine cotată pentru vizitarea Muzeului Aurului și a obiectivelor din Munții Metaliferi."],"facts":[{"label":"Adresă","value":"Str. Vânătorilor nr. 20, Brad"},{"label":"Deschisă","value":"2001, clasificare 2 stele"},{"label":"Camere","value":"5 camere duble, 10 locuri"},{"label":"Contact","value":"tel. 0740 841 239 · contact@pensiuneairina.ro · pensiuneairina.ro"}]},"en":{"tagline":"A family guesthouse opened in 2001, with 5 double rooms, in Brad.","description":["Pensiunea Irina has operated since 2001 at 20 Vânătorilor Street, in Brad, classified as a 2-star establishment by the Ministry of Tourism. It has 5 double rooms, with a total capacity of 10 guests, each with a private bathroom, air conditioning, LED TV and its own heating.","The guesthouse has parking and a dining area with a kitchenette, making it a well-rated option for visiting the Gold Museum and the sights of the Metaliferi Mountains."],"facts":[{"label":"Address","value":"20 Vânătorilor Street, Brad"},{"label":"Opened","value":"2001, 2-star classification"},{"label":"Rooms","value":"5 double rooms, 10 guests"},{"label":"Contact","value":"phone +40 740 841 239 · contact@pensiuneairina.ro · pensiuneairina.ro"}]}},{"id":"pensiunea-ana-maria-brad","name":"Pensiunea Ana Maria","category":{"ro":"Cazare","en":"Accommodation"},"area":"Brad","hasReviews":true,"season":"tot-anul","images":["images/pensiunea-ana-maria-brad.jpg"],"photoCredit":{"author":"Pensiunea Ana Maria","license":"material promoțional al afacerii","source":"https://pensiuneaanamaria.metro.rest","sourceLabel":"pensiuneaanamaria.metro.rest"},"ro":{"tagline":"Pensiune de 3 stele cu restaurant și 19 camere, pe strada Avram Iancu din Brad.","description":["Pensiunea Ana Maria este situată pe strada Avram Iancu nr. 54, în Brad, la aproximativ 1 km de Muzeul Aurului. Are 19 camere și restaurant propriu, cu bucătărie tradițională românească, fiind una dintre cele mai mari unități de cazare din oraș, potrivită și pentru grupuri sau evenimente."],"facts":[{"label":"Adresă","value":"Str. Avram Iancu nr. 54, Brad"},{"label":"Camere","value":"19 camere, clasificare 3 stele"},{"label":"Facilități","value":"restaurant, parcare"},{"label":"Rezervări","value":"direct sau prin platforme online (Booking.com, Agoda)"},{"label":"Contact","value":"tel. 0736 658 589"}]},"en":{"tagline":"A 3-star guesthouse with a restaurant and 19 rooms, on Avram Iancu Street in Brad.","description":["Pensiunea Ana Maria is at 54 Avram Iancu Street, in Brad, about 1 km from the Gold Museum. It has 19 rooms and its own restaurant serving traditional Romanian food, making it one of the largest places to stay in town, also suited to groups and events."],"facts":[{"label":"Address","value":"54 Avram Iancu Street, Brad"},{"label":"Rooms","value":"19 rooms, 3-star rating"},{"label":"Facilities","value":"restaurant, parking"},{"label":"Booking","value":"directly or via online platforms (Booking.com, Agoda)"},{"label":"Contact","value":"phone +40 736 658 589"}]}},{"id":"pensiunea-phoenix-simeria","name":"Pensiunea Phoenix","category":{"ro":"Cazare","en":"Accommodation"},"area":"Simeria","hasReviews":true,"season":"tot-anul","images":["images/pensiunea-phoenix-simeria.jpg"],"photoCredit":{"author":"Pensiunea Phoenix","license":"material promoțional al afacerii","source":"https://www.facebook.com/profile.php?id=100051468775952","sourceLabel":"Facebook"},"ro":{"tagline":"Pensiune cu 8 camere duble, la marginea Simeriei, pe drumul spre Deva.","description":["Pensiunea Phoenix este situată în satul Sântandrei, aparținător orașului Simeria, la circa 700 de metri de Simeria, pe partea stângă a drumului spre Deva (la aproximativ 10 km de Deva). Dispune de 8 camere duble, oferind o alternativă mai liniștită de cazare în zonă, potrivită ca bază pentru vizitarea Parcului Dendrologic Simeria și a împrejurimilor."],"facts":[{"label":"Adresă","value":"Sântandrei, ferma nr. 5, orașul Simeria"},{"label":"Camere","value":"8 camere duble"},{"label":"Reper","value":"~700 m de Simeria, pe drumul spre Deva"},{"label":"Contact","value":"tel. 0722 379 967"}]},"en":{"tagline":"An 8-room guesthouse on the edge of Simeria, on the road to Deva.","description":["Pensiunea Phoenix is located in Sântandrei village, part of Simeria town, about 700 metres from Simeria, on the left side of the road to Deva (roughly 10 km from Deva). It has 8 double rooms, offering a quieter accommodation option in the area, suited as a base for visiting the Simeria Dendrological Park and its surroundings."],"facts":[{"label":"Address","value":"Sântandrei, farm no. 5, Simeria town"},{"label":"Rooms","value":"8 double rooms"},{"label":"Landmark","value":"~700 m from Simeria, on the road to Deva"},{"label":"Contact","value":"phone +40 722 379 967"}]}},{"id":"atrium-hotel-vulcan","name":"Atrium Hotel","category":{"ro":"Hotel & restaurant","en":"Hotel & restaurant"},"area":"Vulcan","hasReviews":true,"season":"tot-anul","images":["images/atrium-hotel-vulcan.jpg"],"photoCredit":{"author":"Atrium Vulcan","license":"material promoțional al afacerii","source":"https://www.facebook.com/profile.php?id=61587211383992","sourceLabel":"Facebook"},"ro":{"tagline":"Hotel cu design modern, poziționat între stațiunile Straja și Parâng, în Vulcan.","description":["Atrium Hotel este situat pe strada Nicolae Titulescu nr. 44, în municipiul Vulcan, între stațiunile montane Straja și Parâng. Combină un design modern cu elemente rustice montane și dispune de restaurant propriu, bar și terasă, alături de camere de tip deluxe și apartamente executive.","Poziția din Valea Jiului îl recomandă atât drumeților și schiorilor care merg spre Straja sau Parâng, cât și celor care caută un popas confortabil în zonă."],"facts":[{"label":"Adresă","value":"Str. Nicolae Titulescu nr. 44, Vulcan"},{"label":"Camere","value":"camere deluxe, apartamente executive"},{"label":"Facilități","value":"restaurant, bar, terasă"},{"label":"Contact","value":"tel. 0728 244 511 · office@atriumhotel.ro · atriumhotel.ro"}]},"en":{"tagline":"A modern-design hotel between the Straja and Parâng resorts, in Vulcan.","description":["Atrium Hotel is located at 44 Nicolae Titulescu Street, in Vulcan, between the Straja and Parâng mountain resorts. It combines modern design with rustic mountain touches and has its own restaurant, bar and terrace, alongside deluxe rooms and executive apartments.","Its position in the Jiu Valley makes it a good choice both for hikers and skiers heading to Straja or Parâng, and for anyone looking for a comfortable stop in the area."],"facts":[{"label":"Address","value":"44 Nicolae Titulescu Street, Vulcan"},{"label":"Rooms","value":"deluxe rooms, executive apartments"},{"label":"Facilities","value":"restaurant, bar, terrace"},{"label":"Contact","value":"phone +40 728 244 511 · office@atriumhotel.ro · atriumhotel.ro"}]}},{"id":"heaven-inn-vulcan","name":"Heaven Inn","category":{"ro":"Restaurant","en":"Restaurant"},"area":"Vulcan","hasReviews":true,"season":"tot-anul","images":["images/heaven-inn-vulcan.jpg"],"photoCredit":{"author":"Heaven INN","license":"material promoțional al afacerii","source":"https://www.facebook.com/BMDselect","sourceLabel":"Facebook"},"ro":{"tagline":"Restaurant deschis în 2022, cu bucătărie românească și internațională, în centrul Vulcanului.","description":["Heaven Inn este un restaurant deschis în mai 2022 pe Bulevardul Mihai Viteazu nr. 14, în centrul municipiului Vulcan. Are un meniu variat, românesc și internațional, terasă și zonă interioară climatizată, plus opțiunea de comandă și livrare online."],"facts":[{"label":"Adresă","value":"Bd. Mihai Viteazu nr. 14, Vulcan"},{"label":"Deschis","value":"2022"},{"label":"Specific","value":"bucătărie românească și internațională, livrare la domiciliu"},{"label":"Contact","value":"tel. 0790 865 091 · heaven-inn.com"}]},"en":{"tagline":"A restaurant opened in 2022, with Romanian and international cuisine, in central Vulcan.","description":["Heaven Inn is a restaurant opened in May 2022 at 14 Mihai Viteazu boulevard, in central Vulcan. It has a varied Romanian and international menu, a terrace and an air-conditioned indoor area, plus online ordering and delivery."],"facts":[{"label":"Address","value":"14 Mihai Viteazu boulevard, Vulcan"},{"label":"Opened","value":"2022"},{"label":"Cuisine","value":"Romanian and international, home delivery"},{"label":"Contact","value":"phone +40 790 865 091 · heaven-inn.com"}]}},{"id":"pensiunea-retezat-petrosani","name":"Pensiunea Retezat","category":{"ro":"Cazare","en":"Accommodation"},"area":"Uricani","hasReviews":true,"season":"tot-anul","images":["images/pensiunea-retezat.jpg"],"photoCredit":{"author":"Pensiunea Retezat","license":"material promoțional al afacerii","source":"https://pensiunearetezat.com","sourceLabel":"pensiunearetezat.com"},"ro":{"tagline":"Pensiune de familie la poalele Retezatului, în Câmpu lui Neag.","description":["Pensiunea Retezat este situată în Câmpu lui Neag (orașul Uricani), chiar la poalele masivului Retezat, la capătul drumului DN66A dinspre Petroșani. Oferă 15 camere, piscină, restaurant și terasă, fiind un punct de plecare comod pentru vizitarea Parcului Național Retezat.","Pensiunea pune la dispoziția oaspeților și activități de agrement — parc de aventură, călărie și acces la piscină în sezonul cald — potrivite atât pentru familii, cât și pentru drumeți."],"facts":[{"label":"Locație","value":"Câmpu lui Neag, orașul Uricani"},{"label":"Facilități","value":"15 camere, piscină, restaurant, terasă"},{"label":"Contact","value":"tel. 0722 538 551 · office@pensiunearetezat.com · pensiunearetezat.com"}]},"en":{"tagline":"A family guesthouse at the foot of the Retezat, in Câmpu lui Neag.","description":["Pensiunea Retezat is located in Câmpu lui Neag (Uricani town), right at the foot of the Retezat massif, at the end of road DN66A from Petroșani. It offers 15 rooms, a pool, restaurant and terrace, making it a convenient base for visiting Retezat National Park.","The guesthouse also offers recreational activities — an adventure park, horse riding and pool access in the warm season — suited to both families and hikers."],"facts":[{"label":"Location","value":"Câmpu lui Neag, Uricani town"},{"label":"Facilities","value":"15 rooms, pool, restaurant, terrace"},{"label":"Contact","value":"phone +40 722 538 551 · office@pensiunearetezat.com · pensiunearetezat.com"}]}},{"id":"hotel-rusu-parang","name":"Hotel Rusu","category":{"ro":"Hotel & restaurant","en":"Hotel & restaurant"},"area":"Petroșani","coords":[45.390162,23.4377853],"hasReviews":true,"season":"tot-anul","images":["images/hotel-rusu-parang.jpg"],"photoCredit":{"author":"Hotel Rusu","license":"material promoțional al afacerii","source":"https://www.hotelrusu.ro","sourceLabel":"hotelrusu.ro"},"ro":{"tagline":"Hotel de altitudine (1.168 m) în stațiunea Parâng, la cca. 10 km de Petroșani.","description":["Hotel Rusu este situat direct în masivul Parâng, la altitudinea de 1.168 m, la aproximativ 10 km de municipiul Petroșani. Oferă acces facil la pârtiile de schi din zonă și dispune de o zonă de wellness cu ciubăr și saună.","Poziția izolată, în mijlocul pădurii de munte, îl recomandă atât pentru sejururi de schi iarna, cât și pentru drumeții vara."],"facts":[{"label":"Altitudine","value":"1.168 m, Masivul Parâng"},{"label":"Contact","value":"tel. 0742 087 221 · info@hotelrusu.ro · hotelrusu.ro"}]},"en":{"tagline":"A mountain hotel at 1,168 m altitude in the Parâng resort, about 10 km from Petroșani.","description":["Hotel Rusu is located directly in the Parâng massif, at an altitude of 1,168 m, about 10 km from the city of Petroșani. It offers easy access to the area's ski slopes and has a wellness area with a hot tub and sauna.","Its secluded position, in the middle of the mountain forest, makes it suitable both for winter ski stays and summer hikes."],"facts":[{"label":"Altitude","value":"1,168 m, Parâng massif"},{"label":"Contact","value":"phone +40 742 087 221 · info@hotelrusu.ro · hotelrusu.ro"}]}},{"id":"pensiunea-bujor-de-munte-petrosani","name":"Pensiunea Bujor de Munte","category":{"ro":"Cazare","en":"Accommodation"},"area":"Petroșani","hasReviews":true,"season":"tot-anul","images":["images/pensiunea-bujor-de-munte-petrosani.jpg"],"photoCredit":{"author":"Pensiunea Bujor de Munte","license":"material promoțional al afacerii","source":"https://bujordemunte.ro","sourceLabel":"bujordemunte.ro"},"ro":{"tagline":"Pensiune 3 stele la poalele Parângului, cu 17 camere și 2 apartamente.","description":["Pensiunea Bujor de Munte este situată pe Strada Bujorului, în stațiunea Parâng, la aproximativ 12 km de Petroșani. Oferă 17 camere duble și 2 apartamente, toate cu internet, minibar și baie proprie.","Dispune de restaurant-bar pentru 45 de persoane și sală de conferințe pentru 50 de persoane, fiind potrivită atât pentru sejururi turistice, cât și pentru evenimente de grup."],"facts":[{"label":"Locație","value":"Strada Bujorului, stațiunea Parâng, cca. 12 km de Petroșani"},{"label":"Camere","value":"17 camere duble + 2 apartamente"},{"label":"Contact","value":"tel. 0254 549 060 / 0735 553 140 · rezervari@bujordemunte.ro · bujordemunte.ro"}]},"en":{"tagline":"A 3-star guesthouse at the foot of the Parâng mountains, with 17 rooms and 2 apartments.","description":["Pensiunea Bujor de Munte is located on Bujorului Street, in the Parâng resort, about 12 km from Petroșani. It offers 17 double rooms and 2 apartments, all with internet, a minibar and a private bathroom.","It has a restaurant-bar for 45 people and a conference room for 50 people, making it suitable both for tourist stays and group events."],"facts":[{"label":"Location","value":"Bujorului Street, Parâng resort, about 12 km from Petroșani"},{"label":"Rooms","value":"17 double rooms + 2 apartments"},{"label":"Contact","value":"phone +40 254 549 060 / +40 735 553 140 · rezervari@bujordemunte.ro · bujordemunte.ro"}]}},{"id":"pensiunea-floare-de-colt-petrosani","name":"Pensiunea Floare de Colț","category":{"ro":"Cazare","en":"Accommodation"},"area":"Petroșani","hasReviews":true,"season":"tot-anul","images":["images/pensiunea-floare-de-colt-petrosani.jpg"],"photoCredit":{"author":"Pensiunea Floare de Colț","license":"material promoțional al afacerii","source":"https://floaredecolthd.ro","sourceLabel":"floaredecolthd.ro"},"ro":{"tagline":"Pensiune cu restaurant la ieșirea din Petroșani spre Defileul Jiului, pe strada Livezeni (DN66).","description":["Pensiunea Floare de Colț este situată pe strada Livezeni nr. 36, la ieșirea din Petroșani spre Defileul Jiului, pe DN66 — un punct de plecare comod spre Parâng, Straja sau Defileu.","Are camere duble, twin, triple și cvadruple, plus restaurant propriu cu preparate tradiționale și internaționale, grădină și o sală pentru evenimente de familie."],"facts":[{"label":"Adresă","value":"Str. Livezeni nr. 36, Petroșani"},{"label":"Facilități","value":"restaurant, grădină, sală de evenimente"},{"label":"Contact","value":"tel. 0254 548 563 / 0744 584 813 · pensiune@floaredecolthd.ro · floaredecolthd.ro"}]},"en":{"tagline":"A guesthouse with a restaurant on the way out of Petroșani towards the Jiu Gorge, on Livezeni Street (DN66).","description":["Pensiunea Floare de Colț is at Livezeni Street no. 36, where Petroșani ends and the road (DN66) enters the Jiu Gorge — a handy base for Parâng, Straja or the gorge itself.","It has double, twin, triple and quadruple rooms, plus its own restaurant serving Romanian and international dishes, a garden and a hall for family events."],"facts":[{"label":"Address","value":"Str. Livezeni no. 36, Petroșani"},{"label":"Facilities","value":"restaurant, garden, event hall"},{"label":"Contact","value":"phone +40 254 548 563 / +40 744 584 813 · pensiune@floaredecolthd.ro · floaredecolthd.ro"}]}},{"id":"complex-turistic-valea-mosului-petrosani","name":"Complex Turistic Valea Moșului","category":{"ro":"Cazare","en":"Accommodation"},"area":"Petroșani","hasReviews":true,"season":"tot-anul","images":["images/complex-turistic-valea-mosului-petrosani.jpg"],"photoCredit":{"author":"Complex Valea Moșului","license":"material promoțional al afacerii","source":"https://www.valeamosului.ro","sourceLabel":"valeamosului.ro"},"ro":{"tagline":"Complex turistic în mijlocul naturii, la poalele Parângului.","description":["Complex Turistic Valea Moșului este situat pe strada Dărănești nr. 73C, într-o locație liniștită, la poalele masivului Parâng."],"facts":[{"label":"Adresă","value":"Str. Dărănești nr. 73C, Petroșani"}]},"en":{"tagline":"A tourist complex surrounded by nature, at the foot of the Parâng mountains.","description":["Complex Turistic Valea Moșului is located on Dărănești Street no. 73C, in a quiet setting at the foot of the Parâng massif."],"facts":[{"label":"Address","value":"Str. Dărănești no. 73C, Petroșani"}]}},{"id":"cabana-la-cassian-vulcan","name":"Cabana la Cassian","category":{"ro":"Cazare","en":"Accommodation"},"area":"Vulcan","hasReviews":true,"season":"tot-anul","images":["images/cabana-la-cassian-vulcan.jpg"],"photoCredit":{"author":"Cabana La Cassian","license":"material promoțional al afacerii","source":"https://www.facebook.com/CabanaLaCassian","sourceLabel":"Facebook"},"ro":{"tagline":"Cabană pe strada Decebal, în orașul Vulcan.","description":["Cabana la Cassian este situată pe strada Decebal nr. 153, în orașul Vulcan, aproape de accesul spre stațiunea Straja."],"facts":[{"label":"Adresă","value":"Str. Decebal nr. 153, Vulcan"}]},"en":{"tagline":"A mountain cabin on Decebal Street, in the town of Vulcan.","description":["Cabana la Cassian is located on Decebal Street no. 153, in the town of Vulcan, close to the access road to the Straja resort."],"facts":[{"label":"Address","value":"Str. Decebal no. 153, Vulcan"}]}},{"id":"pensiunea-paradisul-verde-vulcan","name":"Pensiunea Paradisul Verde","category":{"ro":"Cazare","en":"Accommodation"},"area":"Vulcan","hasReviews":true,"season":"tot-anul","images":["images/pensiunea-paradisul-verde-vulcan.jpg"],"photoCredit":{"author":"Paradisul Verde","license":"material promoțional al afacerii","source":"https://www.facebook.com/paradisulverde.hd","sourceLabel":"Facebook"},"ro":{"tagline":"Pensiune pe strada Socănească, în Vulcan, la cca. 15 km de Straja.","description":["Pensiunea Paradisul Verde este situată pe strada Socănească nr. 8, în municipiul Vulcan, la aproximativ 15 km de stațiunea Straja. Oferă bucătărie tradițională și servicii de restaurant."],"facts":[{"label":"Adresă","value":"Str. Socănească nr. 8, Vulcan"}]},"en":{"tagline":"A guesthouse on Socănească Street, in Vulcan, about 15 km from Straja.","description":["Pensiunea Paradisul Verde is located on Socănească Street no. 8, in the town of Vulcan, about 15 km from the Straja resort. It offers traditional cuisine and restaurant service."],"facts":[{"label":"Address","value":"Str. Socănească no. 8, Vulcan"}]}},{"id":"cabana-casa-ozon-vulcan","name":"Cabana Casa Ozon","category":{"ro":"Cazare","en":"Accommodation"},"area":"Vulcan","hasReviews":true,"season":"tot-anul","images":["images/cabana-casa-ozon-vulcan.jpg"],"photoCredit":{"author":"Casa Ozon","license":"material promoțional al afacerii","source":"https://www.facebook.com/casaozon.ozon","sourceLabel":"Facebook"},"ro":{"tagline":"Cabană pe strada Dealul Babii, în Vulcan.","description":["Cabana Casa Ozon este situată pe strada Dealul Babii nr. 18C, în orașul Vulcan, aproape de traseul Dealul Babii și de accesul spre Straja."],"facts":[{"label":"Adresă","value":"Str. Dealul Babii nr. 18C, Vulcan"}]},"en":{"tagline":"A cabin on Dealul Babii Street, in Vulcan.","description":["Cabana Casa Ozon is located on Dealul Babii Street no. 18C, in the town of Vulcan, close to the Dealul Babii trail and the access road to Straja."],"facts":[{"label":"Address","value":"Str. Dealul Babii no. 18C, Vulcan"}]}},{"id":"pensiunea-dor-de-munte-lupeni","name":"Pensiunea Dor de Munte","category":{"ro":"Cazare","en":"Accommodation"},"area":"Lupeni","hasReviews":true,"season":"tot-anul","images":["images/pensiunea-dor-de-munte-lupeni.jpg"],"photoCredit":{"author":"Pensiunea Dor de Munte Straja","license":"material promoțional al afacerii","source":"https://www.facebook.com/DordeMunteStraja","sourceLabel":"Facebook"},"ro":{"tagline":"Pensiune renovată recent în Lupeni, lângă un parc de aventură.","description":["Pensiunea Dor de Munte, din Lupeni, oferă camere spațioase cu baie proprie și televizor smart, cu o capacitate totală de 54 de locuri în 21 de spații de cazare.","La aproximativ 50 m se află un parc de aventură cu perete de cățărare, iar la 100 m sunt mai multe pârtii de schi și snowboard."],"facts":[{"label":"Locație","value":"Lupeni, lângă parcul de aventură"},{"label":"Capacitate","value":"21 spații de cazare, 54 locuri"}]},"en":{"tagline":"A recently renovated guesthouse in Lupeni, next to an adventure park.","description":["Pensiunea Dor de Munte, in Lupeni, offers spacious rooms with private bathroom and smart TV, with a total capacity of 54 beds across 21 accommodation units.","About 50 m away there is an adventure park with a climbing wall, and 100 m away there are several ski and snowboard slopes."],"facts":[{"label":"Location","value":"Lupeni, next to the adventure park"},{"label":"Capacity","value":"21 accommodation units, 54 beds"}]}},{"id":"complexul-montana-lupeni","name":"Complexul Montana","category":{"ro":"Hotel & restaurant","en":"Hotel & restaurant"},"area":"Munții Vâlcan, Lupeni","hasReviews":true,"season":"tot-anul","images":["images/complexul-montana-lupeni.jpg"],"photoCredit":{"author":"Complex Montana - Straja","license":"material promoțional al afacerii","source":"https://www.facebook.com/Cabana.Montana","sourceLabel":"Facebook"},"ro":{"tagline":"Complex 3 stele în Munții Vâlcan, la 1.367 m altitudine.","description":["Complexul Montana este situat direct în Munții Vâlcan, la o altitudine de 1.367 m, în apropierea orașului Lupeni. Oferă cazare de 3 stele și acces facil la trasee montane."],"facts":[{"label":"Altitudine","value":"1.367 m, Munții Vâlcan"}]},"en":{"tagline":"A 3-star complex in the Vâlcan Mountains, at 1,367 m altitude.","description":["Complexul Montana is located directly in the Vâlcan Mountains, at an altitude of 1,367 m, near the town of Lupeni. It offers 3-star accommodation and easy access to mountain trails."],"facts":[{"label":"Altitude","value":"1,367 m, Vâlcan Mountains"}]}},{"id":"vila-casa-cu-tei-lupeni","name":"Vila Casa cu Tei","category":{"ro":"Cazare","en":"Accommodation"},"area":"Lupeni","hasReviews":true,"season":"tot-anul","images":["images/vila-casa-cu-tei-lupeni.jpg"],"photoCredit":{"author":"Vila Casa cu Tei","license":"material promoțional al afacerii","source":"https://www.facebook.com/profile.php?id=61553313236731","sourceLabel":"Facebook"},"ro":{"tagline":"Vilă cu piscină, pe strada Calea Brăii, în Lupeni.","description":["Vila Casa cu Tei este situată pe strada Calea Brăii nr. 116, în orașul Lupeni, și dispune de piscină proprie."],"facts":[{"label":"Adresă","value":"Str. Calea Brăii nr. 116, Lupeni"},{"label":"Facilități","value":"piscină"}]},"en":{"tagline":"A villa with a pool, on Calea Brăii Street, in Lupeni.","description":["Vila Casa cu Tei is located on Calea Brăii Street no. 116, in the town of Lupeni, and has its own swimming pool."],"facts":[{"label":"Address","value":"Str. Calea Brăii no. 116, Lupeni"},{"label":"Facilities","value":"swimming pool"}]}},{"id":"pensiunea-izvorul-maleii-petrila","name":"Pensiunea Izvorul Maleii","category":{"ro":"Cazare","en":"Accommodation"},"area":"Parâng","hasReviews":true,"season":"tot-anul","images":["images/pensiunea-izvorul-maleii-petrila.jpg"],"photoCredit":{"author":"Izvorul Maleii","license":"material promoțional al afacerii","source":"https://www.booking.com/hotel/ro/izvorul-maleii.html","sourceLabel":"Booking.com"},"ro":{"tagline":"Pensiune bine cotată în stațiunea Parâng, la 1.100 m, la circa 150 m de telescaun.","description":["Pensiunea Izvorul Maleii se află în stațiunea Parâng (pe teritoriul orașului Petrila), la aproximativ 1.100 m altitudine, într-o zonă liniștită lângă pârâul Maleia, la circa 150 m de telescaun și la aproximativ 8 km de Petroșani."],"facts":[{"label":"Adresă","value":"Jieț (zona telescaun) nr. 1T, stațiunea Parâng, Petrila"},{"label":"Altitudine","value":"cca. 1.100 m"}]},"en":{"tagline":"A well-rated guesthouse in the Parâng resort, at 1,100 m, about 150 m from the chairlift.","description":["Pensiunea Izvorul Maleii is in the Parâng resort (within the town of Petrila), at about 1,100 m, in a quiet spot by the Maleia stream, roughly 150 m from the chairlift and about 8 km from Petroșani."],"facts":[{"label":"Address","value":"Jieț (chairlift area) no. 1T, Parâng resort, Petrila"},{"label":"Altitude","value":"about 1,100 m"}]}},{"id":"cabana-brazihouse-petrila","name":"Cabana Brazihouse","category":{"ro":"Cazare","en":"Accommodation"},"area":"Jileț, Petrila","hasReviews":true,"season":"tot-anul","images":["images/cabana-brazihouse-petrila.jpg"],"photoCredit":{"author":"BraziHouse","license":"material promoțional al afacerii","source":"https://www.booking.com/hotel/ro/brazihouse.html","sourceLabel":"Booking.com"},"ro":{"tagline":"Cabană de munte lângă Munții Parâng, în zona Jileț a Petrilei.","description":["Cabana Brazihouse este situată pe strada Jileț nr. 2T, în zona de munte a orașului Petrila, aproape de Munții Parâng."],"facts":[{"label":"Adresă","value":"Jileț nr. 2T, Petrila"}]},"en":{"tagline":"A mountain cabin near the Parâng Mountains, in Petrila's Jileț area.","description":["Cabana Brazihouse is located on Jileț no. 2T, in the mountain area of Petrila, close to the Parâng Mountains."],"facts":[{"label":"Address","value":"Jileț no. 2T, Petrila"}]}},{"id":"cabana-taia-parang-sureanu-petrila","name":"Cabana Taia Parâng-Șureanu","category":{"ro":"Cazare","en":"Accommodation"},"area":"Taia, Petrila","hasReviews":true,"season":"tot-anul","images":["images/cabana-taia-parang-sureanu-petrila.jpg"],"photoCredit":{"author":"Cabana Taia Parâng-Șureanu","license":"material promoțional al afacerii","source":"https://www.facebook.com/profile.php?id=100075600756903","sourceLabel":"Facebook"},"ro":{"tagline":"Cabană montană cu șemineu, pe strada Taia, în Petrila.","description":["Cabana Taia Parâng-Șureanu este situată pe strada Taia nr. 53B, în zona de munte a orașului Petrila, și dispune de șemineu."],"facts":[{"label":"Adresă","value":"Str. Taia nr. 53B, Petrila"},{"label":"Facilități","value":"șemineu"}]},"en":{"tagline":"A mountain cabin with a fireplace, on Taia Street, in Petrila.","description":["Cabana Taia Parâng-Șureanu is located on Taia Street no. 53B, in the mountain area of Petrila, and has a fireplace."],"facts":[{"label":"Address","value":"Str. Taia no. 53B, Petrila"},{"label":"Facilities","value":"fireplace"}]}},{"id":"hotel-germisara-geoagiu-bai","name":"Hotel Germisara Resort & SPA","category":{"ro":"Hotel & restaurant","en":"Hotel & restaurant"},"area":"Geoagiu","coords":[45.9342,23.1661],"hasReviews":true,"season":"tot-anul","images":["images/hotel-germisara.jpg"],"photoCredit":{"author":"Hotel Germisara","license":"material promoțional al afacerii","source":"https://hotelgermisara.ro","sourceLabel":"hotelgermisara.ro"},"ro":{"tagline":"Hotel de 4 stele în stațiunea Geoagiu-Băi, cu piscine cu apă termală, bază de tratament și restaurant.","description":["Hotel Germisara Resort & SPA este unul dintre principalele hoteluri ale stațiunii Geoagiu-Băi, cu 144 de camere și apartamente. Are două piscine cu apă termală pentru tratament, o zonă de wellness și spa și un centru de tratament medical cu programe curative, profilactice și de recuperare.","Restaurantul „Bun Gust” are 200 de locuri și terasă de vară. Termele romane Germisara și ștrandul termal al stațiunii sunt în apropiere."],"facts":[{"label":"Adresă","value":"Str. Germisara nr. 1B, Geoagiu-Băi"},{"label":"Clasificare","value":"4 stele"},{"label":"Facilități","value":"144 de camere și apartamente, piscine termale, spa, bază de tratament, restaurant cu 200 de locuri"},{"label":"Contact","value":"tel. 0372 541 000 · office@hotelgermisara.ro · hotelgermisara.ro"}]},"en":{"tagline":"A 4-star hotel in the Geoagiu-Băi spa resort, with thermal pools, a treatment centre and a restaurant.","description":["Hotel Germisara Resort & SPA is one of the main hotels of the Geoagiu-Băi spa, with 144 rooms and apartments. It has two thermal-water treatment pools, a wellness and spa area, and a medical treatment centre with curative, preventive and rehabilitation programmes.","The \"Bun Gust\" restaurant seats 200 and has a summer terrace. The Roman baths of Germisara and the resort's thermal lido are close by."],"facts":[{"label":"Address","value":"Str. Germisara 1B, Geoagiu-Băi"},{"label":"Rating","value":"4 stars"},{"label":"Facilities","value":"144 rooms and apartments, thermal pools, spa, treatment centre, 200-seat restaurant"},{"label":"Contact","value":"tel. +40 372 541 000 · office@hotelgermisara.ro · hotelgermisara.ro"}]}},{"id":"pensiunea-sarmis-sarmizegetusa","name":"Pensiunea Sarmis","category":{"ro":"Cazare","en":"Accommodation"},"area":"Sarmizegetusa","hasReviews":true,"season":"tot-anul","images":["images/pensiunea-sarmis.jpg"],"photoCredit":{"author":"Pensiunea Sarmis","license":"material promoțional al afacerii","source":"https://www.pensiuneasarmis.ro","sourceLabel":"pensiuneasarmis.ro"},"ro":{"tagline":"Pensiune cu restaurant tradițional în satul Sarmizegetusa, lângă ruinele cetății Ulpia Traiana.","description":["Pensiunea Sarmis se află în satul Sarmizegetusa, aproape de situl Ulpia Traiana Sarmizegetusa, capitala Daciei romane, la poalele Retezatului. Oferă cazare și un restaurant cu mâncăruri tradiționale românești.","E un punct de plecare comod pentru Ulpia Traiana, bisericile medievale din Densuș și Peșteana și pentru drumurile spre Retezat. Pensiunea acceptă carduri de vacanță."],"facts":[{"label":"Locație","value":"Sarmizegetusa nr. 82, comuna Sarmizegetusa"},{"label":"Facilități","value":"cazare, restaurant cu bucătărie tradițională"},{"label":"Plată","value":"carduri bancare și carduri de vacanță"},{"label":"Contact","value":"tel. 0744 794 051 · office@pensiuneasarmis.ro · pensiuneasarmis.ro"}]},"en":{"tagline":"A guesthouse with a traditional restaurant in Sarmizegetusa village, next to the ruins of Ulpia Traiana.","description":["Pensiunea Sarmis is in the village of Sarmizegetusa, close to the site of Ulpia Traiana Sarmizegetusa, capital of Roman Dacia, at the foot of the Retezat. It offers rooms and a restaurant serving traditional Romanian food.","It is a convenient base for Ulpia Traiana, the medieval churches of Densuș and Peșteana, and the roads into the Retezat. Holiday vouchers are accepted."],"facts":[{"label":"Location","value":"Sarmizegetusa no. 82, Sarmizegetusa commune"},{"label":"Facilities","value":"rooms, restaurant with traditional cuisine"},{"label":"Payment","value":"bank cards and holiday vouchers"},{"label":"Contact","value":"tel. +40 744 794 051 · office@pensiuneasarmis.ro · pensiuneasarmis.ro"}]}}];
